import type {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../../types/sessionStore.js';
import {setLogger} from '../../shared/logger.js';

const unusedOrchestrator = {
  processMessageStream: () => {
    throw new Error('list_sessions must never invoke the orchestrator');
  },
} as unknown as ChatOrchestrator;

const baseStore = (): SessionStore => ({
  create: (sessionId, userId) => ({sessionId, userId, entries: []}),
  get: () => undefined,
  delete: () => false,
  count: () => 0,
  clear: () => undefined,
});

const sendListFrame = async (
  rawMessage: unknown,
  sessionStore?: SessionStore,
  userId: string | number = 'u1'
): Promise<OutgoingMessage[]> => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const session: ChatSession = {sessionId: 's1', userId, entries: []};
  const handle =
    sessionStore === undefined
      ? createMessageHandler(unusedOrchestrator)
      : createMessageHandler(unusedOrchestrator, sessionStore);
  await handle(ws, session, rawMessage);
  return sent;
};

describe('handling list_sessions in the websocket message handler', () => {
  const errorLogs: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];

  beforeEach(() => {
    errorLogs.length = 0;
    setLogger({
      debug: () => undefined,
      info: () => undefined,
      warn: () => undefined,
      error: (category, message, fields) => void errorLogs.push({category, message, fields}),
    });
  });

  afterEach(() => {
    setLogger();
  });

  it('lists summaries for session.userId with ISO dates, answers empty without listFor, and logs SERVER_ERROR on failure', async () => {
    const recorded: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-02-01T10:00:00.000Z'),
        updatedAt: new Date('2026-02-01T10:05:00.000Z'),
        entryCount: 3,
      },
    ];
    const listingStore: SessionStore = {
      ...baseStore(),
      listFor: (userId, options) => {
        recorded.push({userId, options});
        return summaries;
      },
    };
    const rejectingStore: SessionStore = {
      ...baseStore(),
      listFor: () => Promise.reject(new Error('database offline')),
    };
    const throwingStringStore: SessionStore = {
      ...baseStore(),
      listFor: () => Promise.reject('connection reset'),
    };
    const before: SessionCursor = {updatedAt: '2026-02-01T12:00:00.000Z', sessionId: 's9'};

    const listed = await sendListFrame({type: 'list_sessions', limit: 5, before, userId: 'u2'}, listingStore, 'u1');
    const withoutStore = await sendListFrame({type: 'list_sessions'});
    const withoutListFor = await sendListFrame({type: 'list_sessions'}, baseStore());
    const rejectedError = await sendListFrame({type: 'list_sessions'}, rejectingStore, 'u1');
    const rejectedString = await sendListFrame({type: 'list_sessions'}, throwingStringStore, 'u7');

    expect({
      recorded,
